REGISTER DQ report_agrees TABLE lightning.metastore.registry_audit.stage_audit.stage_check AS
(report_t IS NULL OR recorded_t IS NULL OR regexp_extract(upper(recorded_t), 'T(IS|X|[0-4])', 0) = '' OR regexp_extract(upper(recorded_t), 'T(IS|X|[0-4])', 0) = regexp_extract(upper(report_t), 'T(IS|X|[0-4])', 0)) AND (report_n IS NULL OR recorded_n IS NULL OR regexp_extract(upper(recorded_n), 'N(X|[0-3])', 0) = '' OR regexp_extract(upper(recorded_n), 'N(X|[0-3])', 0) = regexp_extract(upper(report_n), 'N(X|[0-3])', 0))
